mapper.update:
update ai_run
set status = case when status = 'DISPATCHING' then 'RUNNING' else status end,
    runtime_instance_id = case
        when runtime_instance_id is null or runtime_instance_id = 'direct' then #{instanceId}
        else runtime_instance_id
    end,
    lease_owner = case
        when lease_owner is null or lease_owner = 'direct' then #{instanceId}
        else lease_owner
    end,
    lease_until = now() + make_interval(secs => #{leaseSeconds}), last_heartbeat_at = now(),
    updated_at = now()
where id = #{id} and execution_token = #{executionToken}
  and (runtime_instance_id = #{instanceId}
       or ((runtime_instance_id is null or runtime_instance_id = 'direct') and status = 'DISPATCHING'))
  and status in ('DISPATCHING', 'RUNNING', 'CANCEL_REQUESTED')
  and (lease_until is null or lease_until > now())
  and (deadline_at is null or deadline_at > now())

